import { path, ts, FileSystem } from '@servicenow/sdk-build-core'
import type { Project } from '../../project'

// ============================================================================
// Types & Configuration
// ============================================================================

/**
 * Represents a .d.now.ts file with its metadata
 */
export type FileInfo = {
    scope: string
    fileName: string
    exportName: string
    filePath: string
}

// ============================================================================
// File Scanning Functions
// ============================================================================

/**
 * Scans for all .d.now.ts files in the fluent directory
 * @param fs - File system
 * @param fluentTypeDir - Root fluent types directory
 * @returns List of all .d.now.ts files found
 */
export function scanForNowFiles(fs: FileSystem, fluentTypeDir: string): FileInfo[] {
    const allFiles: FileInfo[] = []

    // Scan the entire fluent directory to include ALL existing files
    // This ensures parent indexes include all subdirectories, not just newly added ones
    scanDirectory(fs, fluentTypeDir, fluentTypeDir, allFiles)

    return allFiles
}

/**
 * Recursively scans a directory for .d.now.ts files
 */
function scanDirectory(fs: FileSystem, fluentTypeDir: string, dir: string, files: FileInfo[]): void {
    if (!FileSystem.existsSync(fs, dir)) {
        return
    }

    const entries = fs.readdirSync(dir, { withFileTypes: true })

    for (const entry of entries) {
        const fullPath = path.join(dir, entry.name)

        if (entry.isDirectory()) {
            // Recurse into subdirectories (scope directories)
            scanDirectory(fs, fluentTypeDir, fullPath, files)
        } else if (entry.name.endsWith('.d.now.ts')) {
            // Found a .d.now.ts file - extract metadata and export name from file
            const fileName = path.basename(entry.name, '.d.now.ts')
            const dirPath = path.dirname(fullPath)
            const scope = path.basename(dirPath) // Last directory name = scope

            // Extract the actual export name from the file content
            const exportName = extractExportName(fs, fullPath, fileName)

            files.push({
                scope,
                fileName,
                exportName,
                filePath: fullPath,
            })
        }
    }
}

/**
 * Extracts the export name from a .d.now.ts file
 * Looks for 'export const <name>' pattern in the file content
 * Falls back to fileName if no export found
 */
function extractExportName(fs: FileSystem, filePath: string, fileName: string): string {
    try {
        const content = fs.readFileSync(filePath, { encoding: 'utf-8' })
        // Match: export const <name> =
        const match = content.match(/export\s+const\s+(\w+)\s*=/)
        return match?.[1] ?? fileName
    } catch {
        // If we can't read the file, fall back to fileName
        return fileName
    }
}

// ============================================================================
// Types & Configuration (continued)
// ============================================================================

/**
 * Configuration for generating an index file
 */
export type IndexConfig = {
    dirName: string
    files: FileInfo[]
    filesByScope: Map<string, FileInfo[]>
}

// ============================================================================
// IndexBuilder - Builds configuration for index generation
// ============================================================================

/**
 * Builds configuration for index file generation
 * Responsible for data transformation and grouping
 */
export class IndexBuilder {
    /**
     * Groups files by their index directory
     * @param files - List of files to group
     * @param fluentTypeDir - Root fluent types directory
     * @returns Map of directory path to files in that directory
     */
    groupFilesByDirectory(files: FileInfo[], fluentTypeDir: string): Map<string, FileInfo[]> {
        const filesByDirectory = new Map<string, FileInfo[]>()

        for (const file of files) {
            const indexDir = this.getIndexDir(file.filePath, fluentTypeDir)

            if (!filesByDirectory.has(indexDir)) {
                filesByDirectory.set(indexDir, [])
            }

            const dirFiles = filesByDirectory.get(indexDir)
            if (dirFiles) {
                dirFiles.push(file)
            }
        }

        return filesByDirectory
    }

    /**
     * Builds configuration for a single index file
     * @param dirPath - Directory where index.ts will be created
     * @param files - Files to include in the index
     * @returns Configuration object for index generation
     */
    buildIndexConfig(dirPath: string, files: FileInfo[]): IndexConfig {
        const dirName = path.basename(dirPath)

        return {
            dirName,
            files,
            filesByScope: this.groupFilesByScope(files),
        }
    }

    /**
     * Groups files by their scope
     */
    private groupFilesByScope(files: FileInfo[]): Map<string, FileInfo[]> {
        const filesByScope = new Map<string, FileInfo[]>()

        for (const file of files) {
            if (!filesByScope.has(file.scope)) {
                filesByScope.set(file.scope, [])
            }

            const scopeFiles = filesByScope.get(file.scope)
            if (scopeFiles) {
                scopeFiles.push(file)
            }
        }

        return filesByScope
    }

    /**
     * Gets the directory where the index.ts file should be created
     */
    private getIndexDir(filePath: string, fluentTypeDir: string): string {
        const dirPath = path.dirname(filePath)
        const relativePath = path.relative(fluentTypeDir, dirPath)
        const pathParts = relativePath.split(path.sep)
        return pathParts.length > 1 ? path.join(fluentTypeDir, ...pathParts.slice(0, -1)) : dirPath
    }
}

// ============================================================================
// IndexGenerator - Generates index.ts files using ts-morph
// ============================================================================

/**
 * Generates index.ts files using ts-morph
 * Responsible for code generation only
 */
export class IndexGenerator {
    constructor(
        private readonly fs: FileSystem,
        private readonly project: Project
    ) {}

    /**
     * Generates an index.ts file from configuration
     * @param dirPath - Directory where index.ts should be created
     * @param config - Configuration for the index file
     */
    generateIndexFile(dirPath: string, config: IndexConfig): void {
        const logger = this.project.getLogger()
        // Skip file generation if there's nothing to export
        if (config.files.length === 0) {
            logger.debug(`Skipping empty index for ${config.dirName} (no files and no OOB)`)
            return
        }

        const indexPath = path.join(dirPath, 'index.ts')

        // Create ts-morph project (in-memory)
        const tsMorphProject = new ts.Project({ useInMemoryFileSystem: true })
        const sourceFile = tsMorphProject.createSourceFile('index.ts', '', { overwrite: true })

        // Build the index file structure
        this.addHeader(sourceFile, config)
        this.addImports(sourceFile, config)
        this.addContent(sourceFile, config)

        // Format and save
        sourceFile.formatText()
        const content = sourceFile.getFullText()
        this.fs.writeFileSync(indexPath, content, { encoding: 'utf-8' })
        logger.debug(`Generated index: ${indexPath}`)
    }

    /**
     * Adds the header comment to the file
     */
    private addHeader(sourceFile: ts.SourceFile, config: IndexConfig): void {
        const description = `Custom by Scope\n *\n * Auto-generated - custom ${config.dirName} organized by scope.`

        sourceFile.insertText(
            0,
            `/**
 * ${config.dirName} - ${description}
 */

`
        )
    }

    /**
     * Adds import statements
     */
    private addImports(sourceFile: ts.SourceFile, config: IndexConfig): void {
        // Add custom imports
        if (config.files.length > 0) {
            sourceFile.addImportDeclarations(
                config.files.map((file) => ({
                    namedImports: [file.exportName],
                    moduleSpecifier: `./${file.scope}/${file.fileName}.d.now`,
                }))
            )
        }
    }

    /**
     * Adds the main content (export with scope organization)
     */
    private addContent(sourceFile: ts.SourceFile, config: IndexConfig): void {
        if (config.files.length > 0) {
            this.addExport(sourceFile, config)
        }
    }

    /**
     * Adds the export statement with direct category exports
     */
    private addExport(sourceFile: ts.SourceFile, config: IndexConfig): void {
        // Export each category directly (e.g., export const role = { ... })
        for (const [scope, scopeFiles] of config.filesByScope.entries()) {
            const scopeId = this.toValidIdentifier(scope)
            const fileProps = scopeFiles.map((f) => `${f.exportName}: ${f.exportName}`).join(', ')
            sourceFile.addStatements(`export const ${scopeId} = { ${fileProps} }`)
        }
    }

    /**
     * Converts a string to a valid JavaScript identifier
     * Replaces hyphens with underscores
     */
    private toValidIdentifier(name: string): string {
        return name.replace(/-/g, '_')
    }
}
